  NEW $NAMESPACE
  SET $NAMESPACE = "ITFCOMMON"
  try 
  {



	Do ##class(ITFCOMMON.Utility).WriteToFile("Get Ncid for " _ rep)
	set servicePort = ##class(HddCommonService.HddCommonServicePort).%New()

    // set servicePort.Location = "http://tacweb.co.ihc.com:80/HddWebServicesExt/HddCommonService"

	Do ##class(ITFCOMMON.Utility).WriteToFile( rep _ " " _ domain _ " " _ context)


 	Set list = servicePort.getNcidsForRepresentation(rep, domain, context, "tst") ; 119
 	set prntStr =  "Call returned " _ list.Count()
 	Do ##class(ITFCOMMON.Utility).WriteToFile(prntStr)
 	if (list.Count() < 1)
 	{
	 	   $$$LOGERROR("CallHDD: " _ rep _ ": " _ prntStr)
	 	   Set repNcid = ""
 	}
 	else
 	{
 	For cnt=1:1:list.Count() 
 	{
		  Do ##class(ITFCOMMON.Utility).WriteToFile("NCID for : " _ rep _ " = " _ list.GetAt(cnt))

		  Set ced = servicePort.getPreferredSurfaceForm(list.GetAt(cnt), context, "tst")
		  if $GET(ced)
		  {
		  	Do ##class(ITFCOMMON.Utility).WriteToFile("Pref Name in " _ context _ " context for: " _list.GetAt(cnt) _ " = " _ ced.text)
		  	Set repNcid = list.GetAt(cnt)

		  	Quit
		  }
		  else
		  {

			Set ced = servicePort.getPreferredSurfaceForm(list.GetAt(cnt), "50450833", "tst")
		 	if $GET(ced)
		  	{

		  		Do ##class(ITFCOMMON.Utility).WriteToFile("Set Name in Centricity context for: " _ list.GetAt(cnt) _ " = " _ ced.text)
		  		Set repNcid = list.GetAt(cnt)

		  		Quit
		  	}

		  }

 	  }

 	}
	}  
    CATCH exceptionvar
    {

      Do ##class(ITFCOMMON.Utility).WriteToFile("this is the error routine: " _ exceptionvar.Name _ " " _ exceptionvar.Code _ " " _ exceptionvar.Location)
     // Do file.WriteLine("the error was: " _ $ZERROR)
    }

  NEW $NAMESPACE
  SET $NAMESPACE = "ITFCOMMON"
  try 
  {
  Set file=##class(%File).%New("CallHDD.txt")

	Do file.Open("WSN")
	Do file.WriteLine("Get Rep for " _ ncid)
	Set rep = ""
	set servicePort = ##class(HddCommonService.HddCommonServicePort).%New()

	Do file.WriteLine( "TODAY: " _ $zdate($h))

		  Set ced = servicePort.getPreferredSurfaceForm(ncid, context, "tst")
		  if $GET(ced)
		  {
		  	Write !, "   Pref Name in context for: ",ncid, " = ", ced.text
		  	Do file.WriteLine("Pref Name in context for: " _ ncid _ " = " _ ced.text)
		  	Set rep = ced.text
		  	Quit
		  }


      Do file.Close()

	}  
    CATCH exceptionvar
    {
      Do file.WriteLine("this is the error routine")
     // Do file.WriteLine("the error was: " _ $ZERROR)
    }

